package thaumcraft.artifice.pattern;

import java.util.*;
import java.util.function.Consumer;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.event.entity.EntityJoinLevelEvent;
import net.minecraftforge.event.level.BlockEvent;
import net.minecraftforge.eventbus.api.EventPriority;
import net.minecraftforge.gametest.*;
import thaumcraft.catalog.blocks.CatalogBlocks;

@GameTestHolder("thaumcraft") @PrefixGameTestTemplate(false)
public final class PatternOwnershipGameTests {
    private PatternOwnershipGameTests(){}
    private static final class Placement implements AutoCloseable {
        final GameTestHelper h;final ServerLevel level;final BlockPos pos;final FakePlayer player;final Map<BlockPos,BlockState> saved=new LinkedHashMap<>();
        Placement(GameTestHelper h){this.h=h;level=h.getLevel();var a=h.absolutePos(BlockPos.ZERO);pos=new BlockPos(a.getX()+2,270,a.getZ()+2);for(int x=(pos.getX()-4)>>4;x<=(pos.getX()+4)>>4;x++)for(int z=(pos.getZ()-4)>>4;z<=(pos.getZ()+4)>>4;z++)level.getChunk(x,z);put(pos,Blocks.AIR.defaultBlockState());put(pos.below(),Blocks.STONE.defaultBlockState());player=new FakePlayer(level,new GameProfile(UUID.randomUUID(),"pattern_owner"));player.setGameMode(GameType.SURVIVAL);player.setPos(pos.getX()-2,pos.getY()+1,pos.getZ()+.5);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(CatalogBlocks.block("pattern_crafter")));}
        void put(BlockPos at,BlockState state){saved.putIfAbsent(at.immutable(),level.getBlockState(at));level.setBlock(at,state,3);}
        InteractionResult place(Consumer<BlockEvent.EntityPlaceEvent> observer){MinecraftForge.EVENT_BUS.addListener(EventPriority.HIGHEST,false,BlockEvent.EntityPlaceEvent.class,observer);try{return player.getMainHandItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos.below()).add(0,.5,0),Direction.UP,pos.below(),false)));}finally{MinecraftForge.EVENT_BUS.unregister(observer);}}
        void observes(BlockEvent.EntityPlaceEvent event,ItemStack physical){h.assertTrue(event.getEntity()==player&&event.getPos().equals(pos)&&!level.captureBlockSnapshots&&player.getMainHandItem()==physical&&physical.getCount()==1,"Real Forge placement callback lost physical predebit hand/capturefalse");}
        @Override public void close(){boolean restoring=level.restoringBlockSnapshots;level.restoringBlockSnapshots=true;try{var rows=new ArrayList<>(saved.entrySet());Collections.reverse(rows);for(var row:rows){if(level.getBlockEntity(row.getKey()) instanceof net.minecraft.world.Container container)container.clearContent();level.setBlock(row.getKey(),row.getValue(),3);}}finally{level.restoringBlockSnapshots=restoring;}}
    }
    @GameTest(template="empty") public static void survivalAndCreativeNativePlacementsKeepExactOriginalFacingAndDebit(GameTestHelper h){for(boolean creative:new boolean[]{false,true})for(Direction facing:Direction.Plane.HORIZONTAL)try(var f=new Placement(h)){f.player.setYRot(facing.toYRot());f.player.setGameMode(creative?GameType.CREATIVE:GameType.SURVIVAL);ItemStack physical=f.player.getMainHandItem();int[] callbacks={0};h.assertTrue(f.place(event->{if(event.getEntity()==f.player){f.observes(event,physical);callbacks[0]++;}}).consumesAction()&&callbacks[0]==1&&f.level.getBlockState(f.pos).getValue(PatternCrafterBlock.FACING)==facing&&f.level.getBlockState(f.pos).getValue(PatternCrafterBlock.ENABLED)&&f.level.getBlockEntity(f.pos) instanceof PatternCrafterBlockEntity&&(creative?physical.getCount()==1:physical.isEmpty()),"Original playerhorizontal facing/nativephysical debit changed");}h.succeed();}
    @GameTest(template="empty") public static void canceledNativePlacementCannotDebitOrInstallProvisionalCrafter(GameTestHelper h){try(var f=new Placement(h)){ItemStack physical=f.player.getMainHandItem();h.assertTrue(!f.place(event->{if(event.getEntity()==f.player){f.observes(event,physical);event.setCanceled(true);}}).consumesAction()&&physical.getCount()==1&&f.level.getBlockState(f.pos).isAir(),"Cancelednativeplacement debited/installedfreecrafter");}h.succeed();}
    @GameTest(template="empty") public static void provisionalNbtCreditCannotExecuteBeforeNativePlacementPayment(GameTestHelper h){try(var f=new Placement(h)){f.put(f.pos.above(),Blocks.CHEST.defaultBlockState());f.put(f.pos.below(),Blocks.CHEST.defaultBlockState());var input=(ChestBlockEntity)f.level.getBlockEntity(f.pos.above());var output=(ChestBlockEntity)f.level.getBlockEntity(f.pos.below());input.setItem(0,new ItemStack(Items.GOLD_INGOT,9));ItemStack physical=f.player.getMainHandItem();var payload=new CompoundTag();payload.putFloat("power",5);physical.getOrCreateTag().put("BlockEntityTag",payload);var original=physical.getTag().copy();h.assertTrue(!f.place(event->{if(event.getEntity()!=f.player)return;f.observes(event,physical);var tile=(PatternCrafterBlockEntity)f.level.getBlockEntity(f.pos);h.assertTrue(tile.power()==5,"Native BlockEntityTag did not install paid-credit fixture on provisional tile");for(int i=0;i<40;i++)tile.serverTick();h.assertTrue(tile.pendingOutputCount()==0&&input.countItem(Items.GOLD_INGOT)==9&&output.isEmpty(),"Unpaidprovisionalcrafter executedphysicalrecipe");event.setCanceled(true);}).consumesAction()&&physical.getCount()==1&&original.equals(physical.getTag())&&f.level.getBlockState(f.pos).isAir()&&input.countItem(Items.GOLD_INGOT)==9&&output.isEmpty(),"Canceledcreditedplacement consumedphysicalinputs");}h.succeed();}
    @GameTest(template="empty") public static void canceledCallbackCannotStealForeignHandTargetOrCapturedChest(GameTestHelper h){try(var f=new Placement(h)){ItemStack physical=f.player.getMainHandItem(),foreign=new ItemStack(Items.EMERALD,3);BlockPos at=f.pos.east(3);ChestBlockEntity[] chest={null};h.assertTrue(!f.place(event->{if(event.getEntity()!=f.player)return;f.observes(event,physical);boolean capture=f.level.captureBlockSnapshots;f.level.captureBlockSnapshots=true;try{f.put(at,Blocks.CHEST.defaultBlockState());chest[0]=(ChestBlockEntity)f.level.getBlockEntity(at);chest[0].setItem(0,new ItemStack(Items.DIAMOND,17));}finally{f.level.captureBlockSnapshots=capture;}f.put(f.pos,Blocks.DIAMOND_BLOCK.defaultBlockState());f.player.setItemInHand(InteractionHand.MAIN_HAND,foreign);event.setCanceled(true);}).consumesAction()&&physical.getCount()==1&&f.player.getMainHandItem()==foreign&&foreign.getCount()==3&&f.level.getBlockState(f.pos).is(Blocks.DIAMOND_BLOCK)&&f.level.getBlockEntity(at)==chest[0]&&chest[0].countItem(Items.DIAMOND)==17,"Rollback overwrote foreign captured resources");}h.succeed();}
    @GameTest(template="empty") public static void canceledPaidTeardownDropsPersistAndNativeRetryExecutesExactlyOnce(GameTestHelper h){try(var f=new PatternCrafterGameTests.Fixture(h)){UUID owner=f.tile.ownerId();var data=PatternOutputData.get(f.level);data.add(f.pos,owner,List.of(new ItemStack(Items.GOLD_INGOT,9),new ItemStack(Items.BUCKET)));Consumer<EntityJoinLevelEvent> cancel=event->{if(event.getLevel()==f.level&&event.getEntity() instanceof ItemEntity&&event.getEntity().position().distanceToSqr(Vec3.atCenterOf(f.pos))<2)event.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(cancel);try{f.tile.releasePaidOutputs();h.assertTrue(data.pendingCount(owner)==10&&PatternOutputData.load(data.save(new CompoundTag())).pendingCount(owner)==10,"Canceledphysicaljoins lostsavedpaidresults");}finally{MinecraftForge.EVENT_BUS.unregister(cancel);}data.tick(f.level);int gold=0,buckets=0;for(var entity:f.level.getEntitiesOfClass(ItemEntity.class,new AABB(f.pos).inflate(2))){if(entity.getItem().is(Items.GOLD_INGOT))gold+=entity.getItem().getCount();if(entity.getItem().is(Items.BUCKET))buckets+=entity.getItem().getCount();}data.tick(f.level);h.assertTrue(gold==9&&buckets==1&&data.pendingCount(owner)==0&&PatternOutputData.load(data.save(new CompoundTag())).pendingCount(owner)==0,"Native accepted retry duplicated/missed paidteardown");}h.succeed();}
    @GameTest(template="empty") public static void reentrantAcceptedPhysicalSaveDoesNotSerializeOrReplayTheAlreadyJoinedItem(GameTestHelper h){try(var f=new PatternCrafterGameTests.Fixture(h)){UUID owner=f.tile.ownerId();var data=PatternOutputData.get(f.level);data.add(f.pos,owner,List.of(new ItemStack(Items.EMERALD,7)));int[] seen={0};Consumer<EntityJoinLevelEvent> observe=event->{if(event.getLevel()!=f.level||!(event.getEntity() instanceof ItemEntity)||event.getEntity().position().distanceToSqr(Vec3.atCenterOf(f.pos))>2)return;seen[0]++;h.assertTrue(data.pendingCount(owner)==7&&PatternOutputData.load(data.save(new CompoundTag())).pendingCount(owner)==7,"Prejoincallback lost canceledphysicalownership");data.tick(f.level);};MinecraftForge.EVENT_BUS.addListener(observe);try{f.tile.releasePaidOutputs();}finally{MinecraftForge.EVENT_BUS.unregister(observe);}data.tick(f.level);h.assertTrue(seen[0]==1&&data.pendingCount(owner)==0&&PatternOutputData.load(data.save(new CompoundTag())).pendingCount(owner)==0,"Reentrant nativejoin replayedacceptedphysicalresult");}h.succeed();}
}
